class AreaCalculable(Protocol):
    def area(self) -> float: ...

class Rectangle:
    def __init__(self, width, height):
        self._width, self._height = width, height
    def area(self):
        return self._width * self._height

class Square:
    def __init__(self, side):
        self._side = side
    def area(self):
        return self._side ** 2
